CREATE TABLE logistics.zones (id serial PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, fee_cents bigint NOT NULL DEFAULT 0, free_over_cents bigint, polygon jsonb);
CREATE TABLE logistics.vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reg text UNIQUE NOT NULL, kind text NOT NULL, refrigerated boolean NOT NULL DEFAULT false, capacity_boxes int, active boolean NOT NULL DEFAULT true);
CREATE TABLE logistics.drivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES identity.users(id), licence_code text, prdp_expiry date);
CREATE TABLE logistics.routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, day_of_week smallint NOT NULL, zone_id int REFERENCES logistics.zones(id), vehicle_id uuid REFERENCES logistics.vehicles(id));
CREATE TABLE logistics.slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid REFERENCES logistics.routes(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, capacity int NOT NULL, booked int NOT NULL DEFAULT 0, early_window boolean NOT NULL DEFAULT false);
CREATE TABLE logistics.route_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid REFERENCES logistics.routes(id), run_on date NOT NULL, driver_id uuid REFERENCES logistics.drivers(id), status text NOT NULL DEFAULT 'planned', started_at timestamptz, ended_at timestamptz);
CREATE TABLE logistics.stops (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES logistics.route_runs(id), order_id uuid REFERENCES sales.orders(id), seq int NOT NULL, eta timestamptz, status text NOT NULL DEFAULT 'pending');
CREATE TABLE logistics.deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stop_id uuid UNIQUE REFERENCES logistics.stops(id), arrived_at timestamptz, delivered_at timestamptz, refused_reason text, temperature_celsius numeric(4,1), cash_cents bigint);
CREATE TABLE logistics.proof_of_delivery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid REFERENCES logistics.deliveries(id), signature_url text, photo_urls text[], recipient_name text);
CREATE TABLE logistics.sync_events (id uuid PRIMARY KEY, device_id text NOT NULL, driver_id uuid, type text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), applied boolean NOT NULL DEFAULT false);
